class Index: pass
key=Index()
key.__index__=lambda:0
try: print([10,20][key])
except TypeError: print('type-only')

class Index:
 __index__=None
try: print([10,20][Index()])
except TypeError: print('not-callable')

class Index:
 def __index__(self): return 'bad'
try: print([10,20][Index()])
except TypeError: print('non-int')

events=[]
class Index:
 def __index__(self):
  events.append('index')
  raise ValueError('bad')
value='before'
try: value=[10,20][Index()]
except ValueError: print(value,events)

events=[]
class Index:
 @property
 def __index__(self):
  events.append('bind')
  return lambda:1
print([10,20][Index()],events)

class Index:
 def __index__(self): return 1<<100
print(range(1<<101)[Index()]==1<<100)
try: print([10,20][Index()])
except IndexError: print('out-of-range')
